insert into public.card_definitions (id, category, title, description, effects, choices) values
  ('E01', 'event', 'Year-End Bonus', 'Your boss finally remembered you still work here.', '[["cash",10000000,"bonus"]]'::jsonb, null),
  ('E02', 'event', 'Holiday Bonus Lands', 'The THR hits your account. Your balance smiles for three days.', '[["cash",15000000,"bonus"]]'::jsonb, null),
  ('E03', 'event', 'Side Project', 'A college friend needs a logo. Decent pay, infinite revisions.', '[["cash",6000000]]'::jsonb, null),
  ('E04', 'event', 'Fun Run Door Prize', 'You came for the free T-shirt and went home with a fridge.', '[["cash",5000000]]'::jsonb, null),
  ('E05', 'event', 'Phone Takes a Dive', 'The screen now looks like a map of shortcut alleys.', '[["pay",3000000]]'::jsonb, null),
  ('E06', 'event', 'Motorbike Breaks Down', 'It stalls exactly when you’re in a hurry.', '[]'::jsonb, '[{"l":"Official workshop","fx":[["pay",2500000]]},{"l":"Roadside mechanic","fx":[["pay",1000000],["back",3]],"m":"It ran… for three blocks."}]'::jsonb),
  ('E07', 'event', 'Midnight Flash Sale', '50% off! Things you don’t need suddenly feel essential.', '[]'::jsonb, '[{"l":"Check out and resell","fx":[["gamble",3000000,7000000,50]]},{"l":"Close the app","fx":[]}]'::jsonb),
  ('E08', 'event', 'Dog-Logo Crypto Coin', 'Up 300% this week. Your friends won’t stop posting screenshots.', '[]'::jsonb, '[{"l":"FOMO in Rp5M","fx":[["gamble",5000000,14000000,35]]},{"l":"Pretend you didn’t see it","fx":[]}]'::jsonb),
  ('E09', 'event', 'Instant Loan SMS', '“Funds in 5 minutes!” The interest rate is not mentioned.', '[]'::jsonb, '[{"l":"Take Rp10M now","fx":[["loan",10000000,13000000]],"m":"You must repay Rp13M at your next Payday."},{"l":"Block the number","fx":[]}]'::jsonb),
  ('E10', 'event', 'Going Home for Lebaran', 'Pricey tickets, endless traffic, but home is home. Advance to Payday.', '[["goto",0]]'::jsonb, null),
  ('E11', 'event', 'Concert in the Capital', 'Ticket war at noon. Your fingers are fast today.', '[]'::jsonb, '[{"l":"Buy a ticket (Rp2M) and go","fx":[["pay",2000000],["goto",35]]},{"l":"Watch the livestream","fx":[]}]'::jsonb),
  ('E12', 'event', 'Promo Flight', 'A cheap ticket pops up in a friend’s story.', '[]'::jsonb, '[{"l":"Fly (Rp2M) to the Airport","fx":[["pay",2000000],["goto",27]]},{"l":"Stay home","fx":[]}]'::jsonb),
  ('E13', 'event', 'Promotion!', 'The long meetings paid off. Your name came up.', '[["cash",12000000,"bonus"]]'::jsonb, null),
  ('E14', 'event', 'Restructuring', 'A more polite word for layoffs. You keep your job, not your bonus.', '[["pay",8000000,"layoff"]]'::jsonb, null),
  ('E15', 'event', 'Wedding Season', 'Three invitations, one weekend. Pay Rp1M to every other player.', '[["each",1000000]]'::jsonb, null),
  ('E16', 'event', 'Your Birthday', 'Social media reminded everyone. Collect Rp1M from every player.', '[["collect",1000000]]'::jsonb, null),
  ('E17', 'event', 'Arisan Jackpot', 'Your name came out first at the office arisan. Collect Rp1.5M from every player.', '[["collect",1500000]]'::jsonb, null),
  ('E18', 'event', 'Typo Transfer', 'One wrong digit and your money moved to a stranger.', '[["pay",2000000]]'::jsonb, null),
  ('E19', 'event', 'Online Shopping Scam', 'You ordered sneakers. A neatly wrapped brick arrived.', '[["pay",2500000]]'::jsonb, null),
  ('E20', 'event', 'Freelance Translation', '40 pages due tomorrow morning.', '[["cash",4000000]]'::jsonb, null),
  ('E21', 'event', 'Viral for a Day', 'A million views of you falling off a bicycle.', '[["cash",3000000]]'::jsonb, null),
  ('E22', 'event', 'Dengue Fever', 'Three days in hospital. Mosquitoes don’t discriminate.', '[["pay",6000000,"health"]]'::jsonb, null),
  ('E23', 'event', 'Shortcut Card', 'A friend shares a secret back road. Keep this card to escape the Traffic Jam once.', '[["jamcard"]]'::jsonb, null),
  ('E24', 'event', 'Daytime Headlight Ticket', 'You forgot. The officer didn’t.', '[["pay",1000000]]'::jsonb, null),
  ('E25', 'event', 'Cousin’s Mega Wedding', 'Everyone is invited and everyone brings an envelope. Collect Rp2M from every player.', '[["collect",2000000]]'::jsonb, null),
  ('E26', 'event', 'Viral Fundraiser', 'The internet chips in for whoever is struggling most. The poorest player receives Rp8M.', '[["poorgift",8000000]]'::jsonb, null),
  ('E27', 'event', 'Gotong Royong', 'Neighbors help neighbors. The richest player gives Rp6M to the poorest.', '[["richtax",6000000]]'::jsonb, null),
  ('E28', 'event', 'Office Potluck', 'Everyone brings food, everyone gets a little bonus. Every player receives Rp1M.', '[["allcash",1000000]]'::jsonb, null),
  ('E29', 'event', 'Food Poisoning', 'The night-market sate was suspicious. Pay Rp2M for medicine.', '[["pay",2000000,"health"]]'::jsonb, null),
  ('E30', 'event', 'Lucky Lottery Ticket', 'A scratch card from the minimarket actually won.', '[["cash",7000000]]'::jsonb, null),
  ('R01', 'reality', 'Wedding Invitation', 'An old classmate is getting married. You’re not close, but the envelope is mandatory.', '[]'::jsonb, '[{"l":"Thick envelope","fx":[["pay",2000000]]},{"l":"Standard envelope","fx":[["pay",1000000]]},{"l":"“I’m out of town”","fx":[["jam"]],"m":"Hiding at home turned into a three-day jam."}]'::jsonb),
  ('R02', 'reality', 'Independence Day Dues', 'The neighborhood committee arrives with a notebook and a hopeful smile.', '[["pay",500000]]'::jsonb, null),
  ('R03', 'reality', 'Vehicle Tax Due', 'Your registration reminds you the state has needs too.', '[["pay",2000000]]'::jsonb, null),
  ('R04', 'reality', 'Fuel Price Hike', 'Petrol goes up. Everything else follows. Every player pays Rp2M to the Community Fund.', '[["allpay",2000000]]'::jsonb, null),
  ('R05', 'reality', 'New Toll Road Opens', 'Everything is connected now. Advance to the nearest transport space; pay double rent if it’s owned.', '[["nearest"]]'::jsonb, null),
  ('R06', 'reality', 'Monsoon Floods', 'Streets became rivers. Every player pays Rp500K per house and Rp2M per tower they own.', '[["allrepairs",500000,2000000]]'::jsonb, null),
  ('R07', 'reality', 'Building Inspection', 'An inspector finds your buildings need “adjustments”. Pay Rp1M per house and Rp4M per tower.', '[["repairs",1000000,4000000]]'::jsonb, null),
  ('R08', 'reality', 'Police Checkpoint', 'Papers, please. Go to the Traffic Jam.', '[["jam"]]'::jsonb, null),
  ('R09', 'reality', 'Rush Hour Commute', 'Packed carriage, mystery aromas, feet not touching the floor.', '[["goto",16]]'::jsonb, null),
  ('R10', 'reality', 'Rupiah Slides', 'Imported things get pricier overnight. Every player pays Rp1M to the Community Fund.', '[["allpay",1000000]]'::jsonb, null),
  ('R11', 'reality', 'Land Values Rise', 'A new mall is planned nearby. Collect Rp1M for each property you own.', '[["perprop",1000000]]'::jsonb, null),
  ('R12', 'reality', 'Tax Refund', 'You overpaid last year. The money comes home.', '[["cash",3000000]]'::jsonb, null),
  ('R13', 'reality', 'Car Free Day', 'A slow walk and a bag of cilok. Move back 3 spaces.', '[["back",3]]'::jsonb, null),
  ('R14', 'reality', 'Blackout', 'The power cut out right before your deadline. Advance to the Power Company.', '[["goto",9]]'::jsonb, null),
  ('R15', 'reality', 'Small Business Grant', 'Your side business gets a government grant.', '[["cash",5000000]]'::jsonb, null),
  ('R16', 'reality', 'Long Weekend', 'Three holidays in a row. Advance to the Rest Area.', '[["goto",18]]'::jsonb, null),
  ('R17', 'reality', 'Mystery Parking Attendant', 'Invisible when you arrive, right there when you leave.', '[["pay",200000]]'::jsonb, null),
  ('R18', 'reality', 'Government Cash Aid', 'Direct cash assistance is disbursed. Every player receives Rp3M.', '[["allcash",3000000]]'::jsonb, null),
  ('R19', 'reality', 'Collective Leave Day', 'A surprise cuti bersama. Every player gets Rp2M in holiday pay.', '[["allcash",2000000,"bonus"]]'::jsonb, null),
  ('R20', 'reality', 'Bali Tourism Boom', 'Flights are full. Owners of Bali and Jakarta collect Rp3M per city; Tour Guides get Rp4M.', '[["regionbonus","navy",3000000],["jobcash",["tourism"],4000000]]'::jsonb, null),
  ('R21', 'reality', 'Nickel Boom', 'Smelters everywhere. Owners of Sulawesi cities collect Rp3M per city.', '[["regionbonus","orange",3000000]]'::jsonb, null),
  ('R22', 'reality', 'New Capital Hype', 'Everyone wants land near the new capital. Owners of Kalimantan cities collect Rp3M per city.', '[["regionbonus","pink",3000000]]'::jsonb, null),
  ('R23', 'reality', 'Coffee Export Boom', 'Indonesian beans are trending abroad. Coffee Farmers get Rp7M; Warung Owners get Rp2M.', '[["jobcash",["farm"],7000000],["jobcash",["biz"],2000000]]'::jsonb, null),
  ('R24', 'reality', 'Ojol Surge Pricing', 'It’s raining at 5 p.m. Ojol Drivers earn Rp5M; everyone else pays Rp500K for rides.', '[["jobcash",["gig"],5000000],["jobpay",["gig"],500000]]'::jsonb, null),
  ('R25', 'reality', 'Civil Servant Pay Raise', 'Government salaries go up. Civil Servants and Teachers get Rp4M.', '[["jobcash",["gov"],4000000]]'::jsonb, null),
  ('R26', 'reality', 'Tech Winter', 'Startups cut staff to “extend runway”. Startup Engineers lose Rp7M.', '[["jobcash",["tech"],-7000000,"layoff"]]'::jsonb, null),
  ('R27', 'reality', 'Algorithm Change', 'Reach drops 80% overnight. Content Creators lose Rp4M.', '[["jobcash",["creative"],-4000000]]'::jsonb, null),
  ('R28', 'reality', 'El Niño Drought', 'The rains don’t come. Coffee Farmers lose Rp5M.', '[["jobcash",["farm"],-5000000]]'::jsonb, null),
  ('R29', 'reality', 'Jakarta Floods', 'The capital is underwater again. Owners of Bali and Jakarta pay Rp2M per city.', '[["regionpay","navy",2000000]]'::jsonb, null),
  ('R30', 'reality', 'Port Strike', 'Ships wait offshore. Every transport owner pays Rp2M per transport space.', '[["typepay","transport",2000000]]'::jsonb, null),
  ('R31', 'reality', 'Interest Rate Hike', 'The central bank raises rates. Every player pays Rp1M per mortgaged property.', '[["mortpay",1000000]]'::jsonb, null),
  ('R32', 'reality', 'Rice Price Spike', 'Nasi is life, and life got pricier. Every player pays Rp1M to the Community Fund.', '[["allpay",1000000]]'::jsonb, null),
  ('R33', 'reality', 'Mass Layoffs', 'Corporate “efficiency”. Office workers (managers, bankers, lawyers, graduates) lose Rp5M.', '[["jobcash",["office"],-5000000,"layoff"]]'::jsonb, null),
  ('R34', 'reality', 'National Shopping Day', 'Online Sellers earn Rp6M and Content Creators Rp3M. Everyone else spends Rp1M.', '[["jobcash",["seller"],6000000],["jobcash",["creative"],3000000],["jobpay",["seller","creative"],1000000]]'::jsonb, null),
  ('R35', 'reality', 'Volcano Ash Cloud', 'Flights grounded across the islands. Tour Guides lose Rp4M; the Airport owner pays Rp3M.', '[["jobcash",["tourism"],-4000000],["ownerpay",27,3000000]]'::jsonb, null),
  ('R36', 'reality', 'Union Wage Deal', 'Factory unions win a raise. Factory Workers get Rp5M.', '[["jobcash",["union"],5000000]]'::jsonb, null);
insert into public.job_definitions (id, name, salary_m, pros, cons, data) values
  ('pns', 'Civil Servant', 14, array['Can’t be laid off', 'Card fines cost you half']::text[], array['Modest salary']::text[], '{"name":"Civil Servant","ic":"🗂️","sal":14,"safe":true,"cardNeg":-50,"tags":["gov"],"pros":["Can’t be laid off","Card fines cost you half"],"cons":["Modest salary"]}'::jsonb),
  ('startup', 'Startup Engineer', 18, array['High salary']::text[], array['Tech-layoff cards hit you', 'Living costs Rp4M each Payday']::text[], '{"name":"Startup Engineer","ic":"🚀","sal":18,"life":4,"tags":["tech"],"pros":["High salary"],"cons":["Tech-layoff cards hit you","Living costs Rp4M each Payday"]}'::jsonb),
