  ('seller', 'Online Seller', 10, array['+Rp1M per property you own each Payday', 'Shopping-day cards pay you']::text[], array['Low base salary']::text[], '{"name":"Online Seller","ic":"📦","sal":10,"perProp":1,"tags":["seller"],"pros":["+Rp1M per property you own each Payday","Shopping-day cards pay you"],"cons":["Low base salary"]}'::jsonb),
  ('agent', 'Property Agent', 12, array['Buy from the bank 10% cheaper']::text[], array['Pay 20% more rent (always out viewing)']::text[], '{"name":"Property Agent","ic":"🏘️","sal":12,"buy":10,"rentPay":20,"tags":["biz"],"pros":["Buy from the bank 10% cheaper"],"cons":["Pay 20% more rent (always out viewing)"]}'::jsonb),
  ('contractor', 'Contractor', 11, array['Houses and towers 25% cheaper']::text[], array['Repair and flood fines doubled']::text[], '{"name":"Contractor","ic":"👷","sal":11,"build":25,"repairs":100,"tags":["biz"],"pros":["Houses and towers 25% cheaper"],"cons":["Repair and flood fines doubled"]}'::jsonb),
  ('manager', 'Corporate Manager', 23, array['Top salary']::text[], array['Car loan: repay Rp25M at your first Payday', 'Mass-layoff cards hit you']::text[], '{"name":"Corporate Manager","ic":"👔","sal":23,"owe":25,"tags":["office"],"pros":["Top salary"],"cons":["Car loan: repay Rp25M at your first Payday","Mass-layoff cards hit you"]}'::jsonb),
  ('grad', 'Fresh Graduate', 8, array['Salary grows Rp2M every Payday', 'Parents chip in Rp15M at the start']::text[], array['Starts at only Rp8M']::text[], '{"name":"Fresh Graduate","ic":"🎓","sal":8,"grow":2,"start":15,"tags":["office"],"pros":["Salary grows Rp2M every Payday","Parents chip in Rp15M at the start"],"cons":["Starts at only Rp8M"]}'::jsonb),
  ('warung', 'Warung Owner', 11, array['+Rp5M whenever you land on a card space or the Night Market']::text[], array['Average salary']::text[], '{"name":"Warung Owner","ic":"🍛","sal":11,"cardSpace":5,"tags":["biz"],"pros":["+Rp5M whenever you land on a card space or the Night Market"],"cons":["Average salary"]}'::jsonb),
  ('doctor', 'Doctor', 19, array['High salary', 'Immune to illness cards']::text[], array['Living costs Rp4M each Payday']::text[], '{"name":"Doctor","ic":"🩺","sal":19,"life":4,"immune":["health"],"tags":["health"],"pros":["High salary","Immune to illness cards"],"cons":["Living costs Rp4M each Payday"]}'::jsonb),
  ('teacher', 'Teacher', 9, array['Private tutoring: collect Rp1M from every player each Payday']::text[], array['Low salary']::text[], '{"name":"Teacher","ic":"📚","sal":9,"tutor":1,"tags":["gov"],"pros":["Private tutoring: collect Rp1M from every player each Payday"],"cons":["Low salary"]}'::jsonb),
  ('guide', 'Tour Guide', 12, array['+75% rent on Bali, Labuan Bajo and transport', 'Tourism-boom cards pay you']::text[], array['Tourism-slump cards hurt']::text[], '{"name":"Tour Guide","ic":"🧭","sal":12,"tourism":75,"tags":["tourism"],"pros":["+75% rent on Bali, Labuan Bajo and transport","Tourism-boom cards pay you"],"cons":["Tourism-slump cards hurt"]}'::jsonb),
  ('banker', 'Banker', 16, array['Mortgages pay 60% and redeem without the 10% fee']::text[], array['Living costs Rp2M each Payday', 'Mass-layoff cards hit you']::text[], '{"name":"Banker","ic":"🏦","sal":16,"life":2,"mortgage":60,"tags":["office"],"pros":["Mortgages pay 60% and redeem without the 10% fee"],"cons":["Living costs Rp2M each Payday","Mass-layoff cards hit you"]}'::jsonb),
  ('lawyer', 'Lawyer', 17, array['Take over cities at 125% instead of 150%', 'Nobody can take over your cities']::text[], array['Living costs Rp3M each Payday']::text[], '{"name":"Lawyer","ic":"⚖️","sal":17,"life":3,"take":125,"protect":true,"tags":["office"],"pros":["Take over cities at 125% instead of 150%","Nobody can take over your cities"],"cons":["Living costs Rp3M each Payday"]}'::jsonb),
  ('factory', 'Factory Worker', 13, array['Union: can’t be laid off', 'Bonus cards pay you Rp3M extra']::text[], array['Average salary']::text[], '{"name":"Factory Worker","ic":"🏭","sal":13,"safe":true,"union":3,"tags":["union"],"pros":["Union: can’t be laid off","Bonus cards pay you Rp3M extra"],"cons":["Average salary"]}'::jsonb),
  ('farmer', 'Coffee Farmer', 9, array['Harvest pays 60–230% of Rp9M', 'Commodity-boom cards pay you']::text[], array['Drought cards hurt']::text[], '{"name":"Coffee Farmer","ic":"☕","sal":9,"var":[60,230],"tags":["farm"],"pros":["Harvest pays 60–230% of Rp9M","Commodity-boom cards pay you"],"cons":["Drought cards hurt"]}'::jsonb);
